#pragma once

// THROWAWAY PROTOTYPE, never for jusprin-dev or a release. It measures what an
// in-app "install and restart" costs on Windows, on the GCP test VM.
//
// Downloads the Windows installer of `version` with Slic3r::Http, checks it
// against the release's SHA256SUMS.txt, then starts a helper with a UAC
// request. The helper waits for this process to exit, runs the installer
// silently and reopens JusPrin through Explorer. Returns true when the helper
// is running, so JusPrin should now quit; false when the person cancelled or
// something failed (a dialog has said so).

#include <string>

class wxWindow;

namespace Slic3r::GUI::JusPrin::Updates {

bool prototype_install_and_restart(wxWindow* parent, const std::string& version);

} // namespace Slic3r::GUI::JusPrin::Updates

// THROWAWAY PROTOTYPE: see InstallRestartPrototype.hpp.
#include "InstallRestartPrototype.hpp"

#ifdef _WIN32

#include "slic3r/GUI/MsgDialog.hpp"
#include "slic3r/Utils/Http.hpp"

#include <boost/filesystem.hpp>
#include <boost/log/trivial.hpp>

#include <openssl/evp.h>

#include <wx/progdlg.h>
#include <wx/msw/wrapwin.h>
#include <shellapi.h>

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <vector>

namespace Slic3r::GUI::JusPrin::Updates {

namespace fs = boost::filesystem;

namespace {

// The same timeline file the helper writes, so one file shows the whole run.
void timeline(const std::string& line)
{
    SYSTEMTIME t;
    GetLocalTime(&t);
    char ts[32];
    snprintf(ts, sizeof ts, "%02d:%02d:%02d.%03d", t.wHour, t.wMinute, t.wSecond, t.wMilliseconds);
    std::ofstream f("C:\\guitest\\ipr\\log.txt", std::ios::app);
    f << ts << " [app pid " << GetCurrentProcessId() << "] " << line << "\n";
    BOOST_LOG_TRIVIAL(warning) << "install-restart prototype: " << line;
}

std::string sha256_of(const fs::path& file)
{
    std::ifstream in(file.wstring(), std::ios::binary);
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha256(), nullptr);
    std::vector<char> buf(1 << 20);
    while (in) {
        in.read(buf.data(), buf.size());
        EVP_DigestUpdate(ctx, buf.data(), size_t(in.gcount()));
    }
    unsigned char md[32];
    unsigned int  n = 0;
    EVP_DigestFinal_ex(ctx, md, &n);
    EVP_MD_CTX_free(ctx);
    std::ostringstream hex;
    for (unsigned i = 0; i < n; ++i)
        hex << std::hex << std::setw(2) << std::setfill('0') << int(md[i]);
    return hex.str();
}

// Downloads `url` into `out` while `progress` shows it. Returns an error, or
// empty on success.
std::string download(const std::string& url, const fs::path& out, wxProgressDialog& progress)
{
    std::string body, error;
    int         last = -1;
    Http::get(url)
        .on_progress([&](Http::Progress p, bool& cancel) {
            if (p.dltotal == 0)
                return;
            const int permille = int(1000.0 * double(p.dlnow) / double(p.dltotal));
            if (permille != last) {
                last = permille;
                if (!progress.Update(permille))
                    cancel = true;
            }
        })
        .on_complete([&](std::string b, unsigned) { body = std::move(b); })
        .on_error([&](std::string, std::string e, unsigned status) { error = e + " (HTTP " + std::to_string(status) + ")"; })
        .perform_sync();
    if (!error.empty())
        return error;
    std::ofstream f(out.wstring(), std::ios::binary);
    f.write(body.data(), std::streamsize(body.size()));
    return f ? std::string() : "could not write " + out.string();
}

void fail(wxWindow* parent, const std::string& what)
{
    timeline("failed: " + what);
    MessageDialog(parent, wxString::FromUTF8("The update did not install: " + what), "JusPrin update", wxOK | wxICON_ERROR).ShowModal();
}

} // namespace

bool prototype_install_and_restart(wxWindow* parent, const std::string& version)
{
    timeline("clicked: install and restart to " + version);
    const fs::path dir = fs::temp_directory_path() / "JusPrinUpdate";
    fs::create_directories(dir);
    const std::string name      = "JusPrin_Windows_Installer_V" + version + "_x64.exe";
    const std::string base      = "https://github.com/TheSpaghettiDetective/JusPrin/releases/download/jusprin/v" + version + "/";
    const fs::path    installer = dir / name;
    const fs::path    sums      = dir / "SHA256SUMS.txt";

    {
        wxProgressDialog progress("JusPrin update", wxString::FromUTF8("Downloading JusPrin " + version + "…"), 1000, parent,
                                  wxPD_APP_MODAL | wxPD_CAN_ABORT | wxPD_AUTO_HIDE | wxPD_ELAPSED_TIME | wxPD_REMAINING_TIME);
        if (const std::string e = download(base + name, installer, progress); !e.empty()) {
            fail(parent, "download: " + e);
            return false;
        }
        timeline("downloaded " + std::to_string(fs::file_size(installer)) + " bytes");
        if (const std::string e = download(base + "SHA256SUMS.txt", sums, progress); !e.empty()) {
            fail(parent, "checksums: " + e);
            return false;
        }
        progress.Pulse(wxString::FromUTF8("Checking the download…"));
        std::string   want;
        std::ifstream in(sums.wstring());
        for (std::string line; std::getline(in, line);)
            if (line.size() > 66 && line.find(name) != std::string::npos)
                want = line.substr(0, 64);
        const std::string got = sha256_of(installer);
        timeline("sha256 want=" + want + " got=" + got);
        if (want.empty() || want != got) {
            fail(parent, "the download does not match SHA256SUMS.txt");
            return false;
        }
    }

    // The helper runs from the temp folder: the installer replaces this
    // install's folder. On the VM it is the prototype's updater_proto.exe.
    const char*    from   = std::getenv("JUSPRIN_UPDATE_HELPER");
    const fs::path helper = dir / "jusprin-update-helper.exe";
    boost::system::error_code ec;
    fs::copy_file(from ? from : "C:\\guitest\\ipr\\updater_proto.exe", helper, fs::copy_option::overwrite_if_exists, ec);
    if (ec) {
        fail(parent, "copying the helper: " + ec.message());
        return false;
    }

    wchar_t exe[MAX_PATH];
    GetModuleFileNameW(nullptr, exe, MAX_PATH);
    const std::wstring params = L"helper " + std::to_wstring(GetCurrentProcessId()) + L" \"" + installer.wstring() + L"\" \"" + exe + L"\"";
    const std::wstring file   = helper.wstring();

    SHELLEXECUTEINFOW sei{sizeof sei};
    sei.fMask        = SEE_MASK_NOCLOSEPROCESS | SEE_MASK_NOASYNC;
    sei.hwnd         = parent ? HWND(parent->GetHandle()) : nullptr;
    sei.lpVerb       = L"runas";
    sei.lpFile       = file.c_str();
    sei.lpParameters = params.c_str();
    sei.nShow        = SW_HIDE;
    timeline("asking for administrator rights (UAC)");
    if (!ShellExecuteExW(&sei)) {
        const DWORD code = GetLastError();
        timeline("UAC refused or failed, GetLastError=" + std::to_string(code));
        if (code == ERROR_CANCELLED)
            MessageDialog(parent, "The update was cancelled. JusPrin was not changed.", "JusPrin update", wxOK).ShowModal();
        else
            fail(parent, "starting the helper failed with Windows error " + std::to_string(code));
        return false;
    }
    if (sei.hProcess)
        CloseHandle(sei.hProcess);
    timeline("UAC accepted, helper running; quitting JusPrin");
    return true;
}

} // namespace Slic3r::GUI::JusPrin::Updates

#else

namespace Slic3r::GUI::JusPrin::Updates {
bool prototype_install_and_restart(wxWindow*, const std::string&) { return false; }
} // namespace Slic3r::GUI::JusPrin::Updates

#endif

