    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
    wc.hbrBackground = HBRUSH(COLOR_WINDOW + 1);
    wc.lpszClassName = L"JusPrinUpdateProgress";
    RegisterClassW(&wc);
    const int w = 460, h = 150;
    RECT wa; SystemParametersInfoW(SPI_GETWORKAREA, 0, &wa, 0);
    g_win = CreateWindowExW(WS_EX_TOPMOST, wc.lpszClassName, title.c_str(), WS_CAPTION | WS_SYSMENU,
                            (wa.left + wa.right - w) / 2, (wa.top + wa.bottom - h) / 2, w, h,
                            nullptr, nullptr, wc.hInstance, nullptr);
    NONCLIENTMETRICSW ncm{sizeof ncm};
    SystemParametersInfoW(SPI_GETNONCLIENTMETRICS, sizeof ncm, &ncm, 0);
    HFONT font = CreateFontIndirectW(&ncm.lfMessageFont);
    g_text = CreateWindowW(L"STATIC", L"", WS_CHILD | WS_VISIBLE, 20, 20, w - 56, 24, g_win, nullptr, wc.hInstance, nullptr);
    SendMessageW(g_text, WM_SETFONT, WPARAM(font), TRUE);
    g_bar = CreateWindowW(PROGRESS_CLASSW, nullptr, WS_CHILD | WS_VISIBLE, 20, 52, w - 56, 22, g_win, nullptr, wc.hInstance, nullptr);
    SendMessageW(g_bar, PBM_SETRANGE32, 0, 1000);
    ShowWindow(g_win, SW_SHOWNORMAL);
    SetForegroundWindow(g_win);
    UpdateWindow(g_win);
