}

static void ui_text(const std::wstring& t) { SetWindowTextW(g_text, t.c_str()); ui_pump(); }

static void ui_marquee(bool on)
{
    LONG_PTR st = GetWindowLongPtrW(g_bar, GWL_STYLE);
    SetWindowLongPtrW(g_bar, GWL_STYLE, on ? (st | PBS_MARQUEE) : (st & ~LONG_PTR(PBS_MARQUEE)));
    SendMessageW(g_bar, PBM_SETMARQUEE, on, 30);
    ui_pump();
}

static void ui_progress(int permille) { SendMessageW(g_bar, PBM_SETPOS, permille, 0); ui_pump(); }

// Waits for a handle while keeping the window responsive.
static void ui_wait(HANDLE h, const std::function<void()>& tick)
{
    for (;;) {
        DWORD r = MsgWaitForMultipleObjects(1, &h, FALSE, 200, QS_ALLINPUT);
        ui_pump();
        if (r == WAIT_OBJECT_0) return;
        if (tick) tick();
    }
}

static unsigned long long folder_bytes(const std::wstring& dir, size_t& files)
{
    unsigned long long total = 0;
    WIN32_FIND_DATAW fd;
    HANDLE f = FindFirstFileW((dir + L"\\*").c_str(), &fd);
    if (f == INVALID_HANDLE_VALUE) return 0;
    do {
        if (!wcscmp(fd.cFileName, L".") || !wcscmp(fd.cFileName, L"..")) continue;
        if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) total += folder_bytes(dir + L"\\" + fd.cFileName, files);
        else { total += (unsigned long long(fd.nFileSizeHigh) << 32) | fd.nFileSizeLow; ++files; }
    } while (FindNextFileW(f, &fd));
    FindClose(f);
    return total;
}

// A visible, titled top-level window of a process named orca-slicer.exe.
static bool app_window_visible()
{
    struct Ctx { bool found = false; } ctx;
    EnumWindows([](HWND h, LPARAM l) -> BOOL {
        if (!IsWindowVisible(h) || GetWindowTextLengthW(h) == 0) return TRUE;
        DWORD pid = 0; GetWindowThreadProcessId(h, &pid);
        HANDLE p = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
        if (!p) return TRUE;
        wchar_t path[MAX_PATH]; DWORD n = MAX_PATH;
        if (QueryFullProcessImageNameW(p, 0, path, &n) && wcsstr(path, L"orca-slicer.exe")) {
            reinterpret_cast<Ctx*>(l)->found = true;
            CloseHandle(p);
            return FALSE;
        }
        CloseHandle(p);
        return TRUE;
    }, LPARAM(&ctx));
    return ctx.found;
}
